-- Extra screenshots per project, shown as a gallery on the project page.
alter table public.projects
  add column gallery jsonb not null default '[]'::jsonb
  check (jsonb_typeof(gallery) = 'array' and jsonb_array_length(gallery) <= 12);

-- Fill in the screenshots for the existing projects. On a fresh database the table is still empty here.
update public.projects p set gallery = g.gallery
from jsonb_to_recordset('[{"slug":"casfyre","gallery":[{"src":"/projects/casfyre-2.jpg","alt":"A service page with the seller, delivery time and three packages to choose from"},{"src":"/projects/casfyre-3.jpg","alt":"Browsing every category, from design to music and audio"},{"src":"/projects/casfyre-4.jpg","alt":"The help page explaining Crafts, Calls and Casefiles"}]},{"slug":"kanto","gallery":[{"src":"/projects/kanto-2.jpg","alt":"A thread with replies, sorted by best, with anonymous and signed-in posters"},{"src":"/projects/kanto-3.jpg","alt":"The community directory, sorted by recent activity"}]},{"slug":"vaikusruum","gallery":[{"src":"/projects/vaikusruum-2.jpg","alt":"The soft yoga and gong page, with a photo of the gong"},{"src":"/projects/vaikusruum-3.jpg","alt":"Private lessons, each with its length and a contact link"},{"src":"/projects/vaikusruum-4.jpg","alt":"The FAQ, with answers that open one at a time"}]},{"slug":"the-last-customer","gallery":[{"src":"/projects/the-last-customer-2.jpg","alt":"A choice between two doors in a dark hallway"},{"src":"/projects/the-last-customer-3.jpg","alt":"A bathroom wall with COME HERE written on it"},{"src":"/projects/the-last-customer-4.jpg","alt":"Pushing a shopping cart down a dim store aisle"}]},{"slug":"snaibo","gallery":[{"src":"/projects/snaibo-2.jpg","alt":"A script running, with its output repeated in the output log"},{"src":"/projects/snaibo-3.jpg","alt":"Creating a new .snaibo script file"}]},{"slug":"flappy-vhs","gallery":[{"src":"/projects/flappy-vhs-2.jpg","alt":"The start menu with three difficulty levels"},{"src":"/projects/flappy-vhs-3.jpg","alt":"The game over screen with the score and high score"}]},{"slug":"invert-nest","gallery":[{"src":"/projects/invert-nest-2.jpg","alt":"A product page for an aquarium, with an order form"},{"src":"/projects/invert-nest-3.jpg","alt":"A category page for amphibian enclosures"}]},{"slug":"jeopardy","gallery":[{"src":"/projects/jeopardy-2.jpg","alt":"The start screen, where you pick the number of teams"},{"src":"/projects/jeopardy-3.jpg","alt":"A question opened from the board"}]},{"slug":"plus-one-speed-per-second","gallery":[{"src":"/projects/plus-one-speed-2.jpg","alt":"The start screen"},{"src":"/projects/plus-one-speed-3.jpg","alt":"Running across the map past a 400 meter dash minigame"}]},{"slug":"crops-vs-creeps","gallery":[{"src":"/projects/crops-vs-creeps-2.jpg","alt":"Choosing a difficulty, with a walnut and a creep in the background"}]}]'::jsonb) as g(slug text, gallery jsonb)
where p.slug = g.slug;
